  function getScopeIdPresets() {
    return SCOPE_ID_PRESETS.map((item) => ({ ...item }));
  }

  function getTemplateStarters(nodeType, fieldName) {
    const byType = TEMPLATE_STARTERS[String(nodeType || "")];
    if (!byType) return [];
    const starters = byType[String(fieldName || "")];
    return starters ? starters.map((item) => ({ ...item })) : [];
  }

  function getAllMappingFields() {
    const fields = new Set();
    Object.values(MAPPING_SECTIONS).forEach((section) => {
      section.fields.forEach((field) => fields.add(field));
    });
    return [...fields];
  }

  function isMappingField(fieldName) {
    return getAllMappingFields().includes(String(fieldName || ""));
  }

  function getSchemaDrivenFields(nodeType) {
    const schema = INSPECTOR_FIELD_SCHEMA[String(nodeType || "").trim()];
    if (!schema?.groups?.length) return [];
    const fields = [];
    const seen = new Set();
    schema.groups.forEach((group) => {
      (group.fields || []).forEach((field) => {
        const key = String(field || "").trim();
        if (!key || seen.has(key)) return;
        seen.add(key);
        fields.push(key);
      });
    });
    return fields;
  }

  /** Types with declarative field groups and no dedicated bespoke inspector. */
  function usesSchemaDrivenInspector(nodeType) {
    const key = String(nodeType || "").trim();
    if (!key || SPECIALIZED_INSPECTOR_TYPES.has(key)) return false;
    return getSchemaDrivenFields(key).length > 0;
  }

  function getCustomInspectorFields(nodeType) {
    const key = String(nodeType || "").trim();
    if (INSPECTOR_CUSTOM_FIELDS[key]) return [...INSPECTOR_CUSTOM_FIELDS[key]];
    // Schema-driven widgets own their fields — avoid duplicating them in the generic form.
    if (usesSchemaDrivenInspector(key)) return getSchemaDrivenFields(key);
    return [];
  }

  function hasSpecializedInspector(nodeType) {
    const key = String(nodeType || "").trim();
    return SPECIALIZED_INSPECTOR_TYPES.has(key) || usesSchemaDrivenInspector(key);
  }

  /** Fixed-host (GitHub/Slack) and allowlisted-host (RabbitMQ/Jira) HTTP API widgets. */
  function isProviderHttpApiType(nodeType) {
    const key = String(nodeType || "").trim();
    if (!key.endsWith("_api")) return false;
    const fields = new Set(getSchemaDrivenFields(key));
    return fields.has("path_template") && fields.has("auth_binding_id");
  }

  /** Any canvas widget that expects a Providers credential binding id. */
  function requiresCredentialBinding(nodeType) {
    const key = String(nodeType || "").trim();
    const fields = new Set([
      ...getSchemaDrivenFields(key),
      ...(INSPECTOR_CUSTOM_FIELDS[key] || []),
    ]);
    if (isProviderHttpApiType(key)) return true;
    return (
      fields.has("auth_binding_id") ||
      fields.has("binding_id") ||
      fields.has("credential_binding_id") ||
      fields.has("token_binding_id") ||
      fields.has("hmac_secret_binding_id")
    );
  }

  function getDataMappingFormat() {
    return { ...DATA_MAPPING_FORMAT };
  }

  function getMappingSections() {
    return { ...MAPPING_SECTIONS };
  }

  function getOutputParamHints(nodeType) {
    const key = String(nodeType || "").trim();
    return OUTPUT_PARAM_HINTS[key] ? [...OUTPUT_PARAM_HINTS[key]] : [];
  }

  const DEFAULT_OUTPUT_FIELD_PATHS = ["status", "body", "response", "output", "message", "data", "result"];

  /** Output field paths for variable pickers — registry hints plus sensible defaults. */
  function getOutputFieldPaths(nodeType) {
    const seen = new Set();
    const paths = [];
    getOutputParamHints(nodeType).forEach((item) => {
      if (!seen.has(item.path)) {
        seen.add(item.path);
        paths.push(item.path);
      }
    });
    DEFAULT_OUTPUT_FIELD_PATHS.forEach((path) => {
      if (!seen.has(path)) {
        seen.add(path);
        paths.push(path);
      }
    });
    return paths;
  }

  function getMappingCategoryForField(field) {
    const meta = CONFIG_FIELDS[field];
    return meta?.mappingCategory || null;
  }

  function getNodeOutputExample(nodeType) {
    const key = String(nodeType || "").trim();
    return NODE_OUTPUT_EXAMPLES[key] ? { ...NODE_OUTPUT_EXAMPLES[key] } : { output: "See run step_results_json" };
  }

  function getTemplateFieldsForNodeType(nodeType) {
    return TEMPLATE_FIELD_HINTS[String(nodeType || "")] || [];
  }

